from typing import Any, Dict


class StepFailed(Exception):
    """Raised by a step that ran but failed (for example a non-zero exit code)."""


class Step:
    """Base class with name, allow_failure and run(ctx). It must not be instantiable on its own."""

    def __init__(self, name: str, allow_failure: bool = False):
        pass

    def run(self, ctx: Dict[str, Any]) -> None:
        pass


class SetStep(Step):
    """Sets ctx[key] = value."""

    def __init__(self, name: str, key: str, value: Any):
        pass


class ShellStep(Step):
    """Fills {placeholders} in command from ctx, runs ctx["shell"](command), fails on a non-zero exit code."""

    def __init__(self, name: str, command: str, allow_failure: bool = False):
        pass


class Pipeline:
    def __init__(self, name: str):
        pass

    def add(self, step: Step) -> "Pipeline":
        pass

    def run(self, ctx: Dict[str, Any]) -> Dict[str, Any]:
        pass


# ---------------------------------------------------------------------------
# Provided — keep this. The tests call run_pipeline(steps, exit_codes, variables):
#   steps are ["set", name, key, value], ["sh", name, command, allow_failure] or ["echo", name];
#   "echo" is a Step subclass defined here, not by you, so Pipeline must not special-case your classes.
#   ctx["shell"] is a fake shell: it records each command and returns exit_codes.get(command, 0).
