from typing import Any, Dict, List


class EchoStep(Step):
    def run(self, ctx):
        ctx.setdefault("log", []).append(self.name)


def _raises(action):
    try:
        action()
        return "no error"
    except Exception as err:
        return type(err).__name__


def _contract():
    class Incomplete(Step):
        pass

    p = Pipeline("probe")
    first = SetStep("a", "k", 1)
    return {
        "abstract_step": _raises(lambda: Step("x")),
        "missing_run": _raises(lambda: Incomplete("x")),
        "add_chains": p.add(first) is p,
        "add_non_step": _raises(lambda: p.add("make test")),
        "duplicate_name": _raises(lambda: p.add(EchoStep("a"))),
        "iterates_steps": [s.name for s in p],
        "shell_step_is_step": isinstance(ShellStep("b", "true"), Step),
    }


def run_pipeline(steps: List[list], exit_codes: Dict[str, int], variables: Dict[str, Any]) -> Dict[str, Any]:
    executed = []

    def shell(command):
        executed.append(command)
        return exit_codes.get(command, 0)

    pipeline = Pipeline("ci")
    for spec in steps:
        kind, name, *rest = spec
        if kind == "set":
            pipeline.add(SetStep(name, rest[0], rest[1]))
        elif kind == "sh":
            pipeline.add(ShellStep(name, rest[0], allow_failure=rest[1]))
        else:
            pipeline.add(EchoStep(name))
    ctx = dict(variables, shell=shell)
    result = pipeline.run(ctx)
    return {"result": result, "executed": executed, "log": ctx.get("log", []),
            "length": len(pipeline), "contract": _contract()}
